package userx_test

import (
	"os"
	"path/filepath"
	"testing"

	"github.com/egdaemon/eg/internal/userx"
	"github.com/stretchr/testify/require"
)

// DO NOT EDIT: This file was auto generated by egautotest.

func TestConfigDirectory(t *testing.T) {
	t.Run("uses CONFIG_DIRECTORY when set", func(t *testing.T) {
		dir := t.TempDir()
		t.Setenv("CONFIG_DIRECTORY", dir)
		require.Equal(t, filepath.Join(dir, "sub", "path"), userx.ConfigDirectory("sub", "path"))
	})

	t.Run("uses XDG_CONFIG_HOME when CONFIG_DIRECTORY is not set", func(t *testing.T) {
		dir := t.TempDir()
		t.Setenv("CONFIG_DIRECTORY", "")
		t.Setenv("XDG_CONFIG_HOME", dir)
		require.Equal(t, filepath.Join(dir, "data"), userx.ConfigDirectory("data"))
	})

	t.Run("falls back to user home .config when no env vars set", func(t *testing.T) {
		t.Setenv("CONFIG_DIRECTORY", "")
		t.Setenv("XDG_CONFIG_HOME", "")
		home, err := os.UserHomeDir()
		require.NoError(t, err)
		require.Equal(t, filepath.Join(home, ".config", "myapp"), userx.ConfigDirectory("myapp"))
	})

	t.Run("returns base directory with no rel", func(t *testing.T) {
		dir := t.TempDir()
		t.Setenv("CONFIG_DIRECTORY", dir)
		require.Equal(t, dir, userx.ConfigDirectory())
	})
}
